-- Snapshot only evidence needed to reconstruct owned quantities at each site's cutoff.
-- The migration baseline is the first known state, never a retrospective opening balance.
CREATE TABLE finance_stock_baseline (started_at TEXT PRIMARY KEY);
INSERT INTO finance_stock_baseline VALUES(strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE finance_stock_history (seq INTEGER PRIMARY KEY, at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), source TEXT NOT NULL, entity TEXT NOT NULL, payload TEXT);
CREATE INDEX idx_fin_stock_history ON finance_stock_history(source,entity,at,seq);
CREATE TRIGGER immutable_fin_stock_history_update BEFORE UPDATE ON finance_stock_history BEGIN SELECT RAISE(ABORT,'immutable stock history'); END;
CREATE TRIGGER immutable_fin_stock_history_delete BEFORE DELETE ON finance_stock_history BEGIN SELECT RAISE(ABORT,'immutable stock history'); END;
INSERT INTO finance_stock_history(source,entity,payload) SELECT 'inventory_balances',json_array(site,channel,sku),json_object('site',site,'channel',channel,'sku',sku,'qty',qty,'reserved_qty',reserved_qty,'pending_shelf_qty',pending_shelf_qty,'quarantine_qty',quarantine_qty) FROM inventory_balances;
CREATE TRIGGER fin_hist_inventory_balances_ai AFTER INSERT ON inventory_balances BEGIN INSERT INTO finance_stock_history(source,entity,payload) VALUES('inventory_balances',json_array(NEW.site,NEW.channel,NEW.sku),json_object('site',NEW.site,'channel',NEW.channel,'sku',NEW.sku,'qty',NEW.qty,'reserved_qty',NEW.reserved_qty,'pending_shelf_qty',NEW.pending_shelf_qty,'quarantine_qty',NEW.quarantine_qty)); END;
